An interviewer asks for a tiny Redux-style store. A candidate writes this. What does it log?

```js
function createStore(reducer, initial) {
  let state = initial;
  const listeners = [];
  return {
    getState: () => state,
    subscribe(fn) { listeners.push(fn); },
    dispatch(action) {
      listeners.forEach((fn) => fn());
      state = reducer(state, action);
    },
  };
}

const store = createStore((s, a) => (a.type === 'inc' ? s + 1 : s), 0);
store.subscribe(() => console.log(store.getState()));
store.dispatch({ type: 'inc' });
store.dispatch({ type: 'inc' });
```

The store's `subscribe` now returns an unsubscribe function. One listener unsubscribes itself the first time it runs. What does this log, and what is the usual fix?

```js
const listeners = [];
function subscribe(fn) {
  listeners.push(fn);
  return () => listeners.splice(listeners.indexOf(fn), 1);
}
function notify() {
  listeners.forEach((fn) => fn());
}

const unsubA = subscribe(() => { console.log('A'); unsubA(); });
subscribe(() => console.log('B'));
subscribe(() => console.log('C'));
notify();
notify();
```

