Given this `classNames` helper, what does the call at the bottom return?

```js
function classNames(...args) {
  const out = [];
  for (const arg of args) {
    if (!arg) continue;
    if (typeof arg === 'string' || typeof arg === 'number') out.push(arg);
    else if (Array.isArray(arg)) {
      const inner = classNames(...arg);
      if (inner) out.push(inner);
    } else if (typeof arg === 'object') {
      for (const [key, on] of Object.entries(arg)) if (on) out.push(key);
    }
  }
  return out.join(' ');
}

classNames('btn', { active: true, disabled: false }, null, ['lg', { round: 1 }], 0, '');
```

`before(n, fn)` should run `fn` for at most the first `n` calls, and later calls should return the last result. What does this log?

```js
function before(n, fn) {
  let count = 0;
  let last;
  return (...args) => {
    if (count < n) {
      count++;
      last = fn(...args);
    }
    return last;
  };
}

const f = before(2, (x) => x * 10);
console.log(f(1), f(2), f(3), f(4));
```

