This function converts every key of a nested API response to snake_case. What does it log, and what is the fix?

```js
const toSnake = (k) => k.replace(/[A-Z]/g, (c) => '_' + c.toLowerCase());

function snakeKeys(v) {
  if (typeof v !== 'object' || v === null) return v;
  return Object.fromEntries(
    Object.entries(v).map(([k, x]) => [toSnake(k), snakeKeys(x)])
  );
}

console.log(JSON.stringify(snakeKeys({ userList: [{ firstName: 'A' }] })));
```

